package com.ilp.bank;

import java.util.function.Supplier;

// Ui.java: page helpers. Students do NOT edit this file.
public class Ui {
    static final String CSS = "*{box-sizing:border-box}body{margin:0;background:#F4F7F9;color:#1d2433;font:16px/1.5 system-ui,-apple-system,\"Segoe UI\",Roboto,Arial,sans-serif}\n.wrap{max-width:760px;margin:0 auto;padding:18px}\n.top{background:linear-gradient(115deg,#21295C,#065A82 60%,#1C7293);color:#fff;border-radius:12px;padding:12px 16px;display:flex;justify-content:space-between;align-items:center;gap:12px}\n.top b{letter-spacing:2px;color:#F2A104;font-size:13px}.prog{flex:1;max-width:300px}.prog small{display:block;text-align:right;font-weight:700}\n.bar{height:10px;background:rgba(255,255,255,.25);border-radius:6px;overflow:hidden}.bar i{display:block;height:100%;background:#F2A104}\n.card{background:#fff;border:1px solid #dde3ea;border-radius:12px;padding:16px;margin-top:14px}\nh1{color:#21295C;margin:6px 0}h2{color:#065A82;margin:6px 0}\ninput{padding:10px 12px;border:1px solid #c9d2dc;border-radius:8px;font:inherit;margin:4px 6px 4px 0;min-width:180px}\nbutton{background:#21295C;color:#fff;border:0;border-radius:8px;padding:10px 18px;font:inherit;font-weight:700;cursor:pointer;margin:4px 6px 4px 0}\nbutton.alt{background:#1C7293}button.amber{background:#F2A104;color:#21295C}\nul{padding-left:20px}li{margin:6px 0}\n.todo{border:2px dashed #b9c2cc;background:#f1f3f5;color:#6b7480;border-radius:8px;padding:8px 12px;margin:6px 0;font-size:14px}\n.todo b{color:#4b5563}.todo.d3{border-color:#d9c79a;background:#fbf7ec}\n.error{border:2px solid #d9534f;background:#fdecea;color:#a12622;border-radius:8px;padding:8px 12px;margin:6px 0;font-size:14px;font-family:Consolas,Menlo,monospace}\n.msg{padding:10px 12px;border-radius:8px;margin:8px 0;font-weight:600}.ok{background:#e7f6ec;color:#1e7b3c}.bad{background:#fdecea;color:#a12622}\n.badge{display:inline-block;background:#21295C;color:#fff;font-size:12px;font-weight:700;border-radius:10px;padding:1px 8px;margin-left:8px}\n.del{text-decoration:none;margin-left:8px}\n.stats{display:flex;gap:12px;flex-wrap:wrap}.stat{background:#eef6f9;border-radius:8px;padding:8px 14px}.stat b{font-size:20px;color:#21295C;display:block}\nfooter{margin-top:18px;text-align:center;color:#5b6474}\n.steps{display:flex;flex-wrap:wrap;gap:6px;margin-top:8px}.steps span{font-size:12px;padding:2px 8px;border-radius:10px;background:#e3e8ee;color:#5b6474}\n.steps span.ok{background:#d6f0de;color:#1e7b3c}.steps span.err{background:#fdecea;color:#a12622}\n";

    public static String esc(Object o) {
        return String.valueOf(o).replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;").replace("\"", "&quot;");
    }

    // Grey box for a step that is not done, red box for a step with an error
    public static String box(int n) {
        String st = Checks.status(n);
        String file = Checks.FILES[n - 1], title = Checks.TITLES[n - 1];
        if (st.startsWith("error")) return "<div class=\"error\">🔴 Step " + n + " (" + file + ") has an " + esc(st) + "</div>";
        boolean d3 = Checks.DAYS[n - 1] == 3;
        return "<div class=\"todo" + (d3 ? " d3" : "") + "\">⬜ <b>Step " + n + ": " + title + "</b>" + (d3 ? " · Day 3" : "")
            + " · not done yet · open <code>" + file + "</code></div>";
    }

    // Use the student's code if the step is done, else show the grey box
    public static String part(int n, Supplier<String> code) {
        if (!Checks.done(n)) return box(n);
        try {
            return String.valueOf(code.get());
        } catch (Throwable e) {
            return "<div class=\"error\">🔴 Step " + n + ": " + esc(e) + "</div>";
        }
    }

    public static String page(String inner) {
        int done = Checks.doneCount(), total = Checks.TOTAL;
        StringBuilder chips = new StringBuilder();
        for (int n = 1; n <= total; n++) {
            String st = Checks.status(n);
            boolean ok = st.equals("done"), err = st.startsWith("error");
            chips.append("<span class=\"").append(ok ? "ok" : err ? "err" : "").append("\">")
                 .append(ok ? "✅" : err ? "🔴" : "⬜").append(" ").append(n).append("</span>");
        }
        return "<!doctype html><html><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">"
            + "<title>My Bank</title><style>" + CSS + "</style></head><body><div class=\"wrap\">"
            + "<div class=\"top\"><div><b>ILP WORKSHOP</b><div>My Bank</div></div>"
            + "<div class=\"prog\"><small>" + done + " / " + total + " steps done</small><div class=\"bar\"><i style=\"width:"
            + Math.round(done * 100.0 / total) + "%\"></i></div></div></div><div class=\"steps\">" + chips + "</div>"
            + inner + "</div></body></html>";
    }
}
